            cfg_dict['mgmt_ip_addr'] = ip
            if self.user_list is not None:
                cfg_dict['user'] = self.user_list[cnt]
            if self.pwd_list is not None:
                cfg_dict['pwd'] = self.pwd_list[cnt]
            if self.interface_in_list is not None:
                cfg_dict['interface_in'] = self.interface_in_list[cnt]
            if self.interface_out_list is not None:
                cfg_dict['interface_out'] = self.interface_out_list[cnt]
            drvr_obj.initialize(cfg_dict)
            cnt = cnt + 1

def cmd_asterix(self, args):
        '''asterix command parser'''
        usage = "usage: asterix <set|start|stop|restart|status>"
        if len(args) == 0:
            print(usage)
            return
        if args[0] == "set":
            self.asterix_settings.command(args[1:])
        elif args[0] == "start":
            self.start_listener()
        elif args[0] == "stop":
            self.stop_listener()
        elif args[0] == "restart":
            self.stop_listener()
            self.start_listener()
        elif args[0] == "status":
            self.print_status()
        else:
            print(usage)

